CREATE TABLE IF NOT EXISTS hs_data_formula_fields(tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),collection text NOT NULL,field_key uuid NOT NULL,version integer NOT NULL CHECK(version>0),definition jsonb NOT NULL,sensitive boolean NOT NULL,created_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,field_key));
CREATE TABLE IF NOT EXISTS hs_data_formula_versions(tenant_id uuid NOT NULL,collection text NOT NULL,field_key uuid NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,sensitive boolean NOT NULL,actor_id text NOT NULL,operation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,collection,field_key,version),UNIQUE(tenant_id,actor_id,operation_id));
CREATE TABLE IF NOT EXISTS hs_data_formula_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,workspace_id text NOT NULL,actor_id text NOT NULL,collection text NOT NULL,field_key uuid NOT NULL,expected_version integer NOT NULL,expected_schema_version integer NOT NULL,definition_hash text NOT NULL,authority_revision text NOT NULL,review_hash text NOT NULL,expires_at timestamptz NOT NULL DEFAULT(clock_timestamp()+interval '10 minutes'));
CREATE TABLE IF NOT EXISTS hs_data_formula_operations(tenant_id uuid NOT NULL,actor_id text NOT NULL,operation_id uuid NOT NULL,request_hash text NOT NULL,collection text NOT NULL,field_key uuid NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id));
